function floatNumbers(result){for(const event of result.events||[]){if(event.type==='miss'){const point=criticalFilm.active?criticalFilm.point(event.target):scene.point(event.target);if(point){const label=element('span',{class:'damage-number miss'},event.reason==='illusion'?'ILLUSION — NO DAMAGE':'MISS — NO DAMAGE');label.style.left=(innerWidth<650?innerWidth/2:point.x)+'px';label.style.top=Math.max(100,Math.min(innerHeight-160,point.y))+'px';$('damage-layer').append(label);setTimeout(()=>label.remove(),1400);}continue;}if(!showNumbers||!event.amount)continue;const point=criticalFilm.active?criticalFilm.point(event.target):scene.point(event.target);if(!point)continue;const label=element('span',{class:'damage-number '+(event.critical?'critical ':'')+(result.skill==='universe'?'cosmic-damage ':'')+(event.type==='damage'?'':'heal')},(event.critical?'✦ ':'')+(event.type==='damage'?'−':'+')+(result.skill==='universe'?event.amount.toLocaleString('en-US'):event.amount)+(event.type==='focus'?' FP':event.status==='poison'?' · POISON':event.guarded?' · GUARD':''));label.style.left=point.x+'px';label.style.top=Math.max(80,Math.min(innerHeight-110,point.y+20))+'px';$('damage-layer').append(label);setTimeout(()=>label.remove(),1400);}}
