 const key=[state.phase,state.stage,state.round,state.cursor].join(':');if(!room&&(state.decisionKey!==key||!state.decisionEndsAt)){state.decisionKey=key;state.decisionEndsAt=Date.now()+20000;save();}const deadline=room?room.decisionEndsAt:state.decisionEndsAt;if(!deadline){node.hidden=true;return;}const left=Math.min(20,Math.max(0,Math.ceil((deadline-Date.now()-(room?online.clockOffset||0:0))/1000)));node.hidden=false;node.textContent=left+'s · '+(state.phase==='story'?'Choose a path':'Choose an action');node.classList.toggle('urgent',left<=5);
 if(!left&&!room){node.hidden=true;if(state.phase==='story'){storyChoice(Math.random()<.5?'accept':'decline');}else{hideModal();const before=structuredClone(state),result=E.randomAct(state);if(result.ok)animate(result,before);}}
